#[inline]
pub unsafe fn __octeon_match_mask(x: u32, y: u32, z: u32) -> bool { (x & z) == (y & z) }

#[inline]
pub unsafe fn __octeon_is_model_compile(arg_model: u32, chip_model: u32) -> bool {
    if (arg_model & OCTEON_38XX_FAMILY_MASK) < OCTEON_CN58XX_PASS1_0 {
        (((arg_model & OM_FLAG_MASK) == (OM_IGNORE_REVISION | OM_CHECK_SUBMODEL)) && __octeon_match_mask(chip_model,arg_model,OCTEON_38XX_MODEL_MASK)) ||
        (((arg_model & OM_FLAG_MASK) == 0) && __octeon_match_mask(chip_model,arg_model,OCTEON_38XX_FAMILY_REV_MASK)) ||
        (((arg_model & OM_FLAG_MASK) == OM_IGNORE_REVISION) && __octeon_match_mask(chip_model,arg_model,OCTEON_38XX_FAMILY_MASK)) ||
        (((arg_model & OM_FLAG_MASK) == OM_CHECK_SUBMODEL) && __octeon_match_mask(chip_model,arg_model,OCTEON_38XX_MODEL_REV_MASK)) ||
        (((arg_model & OM_MATCH_PREVIOUS_MODELS) == OM_MATCH_PREVIOUS_MODELS) && ((chip_model & OCTEON_38XX_MODEL_MASK) < (arg_model & OCTEON_38XX_MODEL_MASK)))
    } else {
        (((arg_model & OM_FLAG_MASK) == (OM_IGNORE_REVISION | OM_CHECK_SUBMODEL)) && __octeon_match_mask(chip_model,arg_model,OCTEON_58XX_MODEL_MASK)) ||
        (((arg_model & OM_FLAG_MASK) == 0) && __octeon_match_mask(chip_model,arg_model,OCTEON_58XX_FAMILY_REV_MASK)) ||
        (((arg_model & OM_FLAG_MASK) == OM_IGNORE_MINOR_REVISION) && __octeon_match_mask(chip_model,arg_model,OCTEON_58XX_MODEL_MINOR_REV_MASK)) ||
        (((arg_model & OM_FLAG_MASK) == OM_IGNORE_REVISION) && __octeon_match_mask(chip_model,arg_model,OCTEON_58XX_FAMILY_MASK)) ||
        (((arg_model & OM_FLAG_MASK) == OM_CHECK_SUBMODEL) && __octeon_match_mask(chip_model,arg_model,OCTEON_58XX_MODEL_MASK)) ||
        (((arg_model & OM_MATCH_5XXX_FAMILY_MODELS) == OM_MATCH_5XXX_FAMILY_MODELS) && (chip_model & OCTEON_PRID_MASK) >= OCTEON_CN58XX_PASS1_0 && (chip_model & OCTEON_PRID_MASK) < OCTEON_CN63XX_PASS1_0) ||
        (((arg_model & OM_MATCH_6XXX_FAMILY_MODELS) == OM_MATCH_6XXX_FAMILY_MODELS) && (chip_model & OCTEON_PRID_MASK) >= OCTEON_CN63XX_PASS1_0 && (chip_model & OCTEON_PRID_MASK) < OCTEON_CNF71XX_PASS1_0) ||
        (((arg_model & OM_MATCH_F7XXX_FAMILY_MODELS) == OM_MATCH_F7XXX_FAMILY_MODELS) && (chip_model & OCTEON_PRID_MASK) >= OCTEON_CNF71XX_PASS1_0 && (chip_model & OCTEON_PRID_MASK) < OCTEON_CN78XX_PASS1_0) ||
        (((arg_model & OM_MATCH_7XXX_FAMILY_MODELS) == OM_MATCH_7XXX_FAMILY_MODELS) && (chip_model & OCTEON_PRID_MASK) >= OCTEON_CN78XX_PASS1_0) ||
        (((arg_model & OM_MATCH_PREVIOUS_MODELS) == OM_MATCH_PREVIOUS_MODELS) && ((chip_model & OCTEON_58XX_MODEL_MASK) < (arg_model & OCTEON_58XX_MODEL_MASK)))
    }
}

#[inline]
pub unsafe fn __octeon_is_model_runtime(model: u32) -> i32 { if __octeon_is_model_compile(model, cvmx_get_proc_id()) { 1 } else { 0 } }
pub const OCTEON_IS_COMMON_BINARY: u32 = 1;
#[inline] pub unsafe fn cvmx_get_octeon_family() -> u32 { cvmx_get_proc_id() & OCTEON_FAMILY_MASK }

